{total(), plural,
      =1 {1 message over the last {{ cells().length }} days}
      other {{{ total() }} messages over the last {{ cells().length }} days}
    }

{coordinator.failedCount(), plural,
          =1 {1 message not sent}
          other {{{ coordinator.failedCount() }} messages not sent}
        }

{coordinator.pendingCount(), plural,
          =1 {1 message queued}
          other {{{ coordinator.pendingCount() }} messages queued}
        }

{offline.pendingCount(), plural,
                =1 {1 local change awaiting sync}
                other {{{ offline.pendingCount() }} local changes awaiting sync}
              }

{sync.blockedOperations(), plural,
                =1 {1 operation needs your attention}
                other {{{ sync.blockedOperations() }} operations need your attention}
              }
